    /**
     * Render an inline SVG icon with customizable size and CSS classes
     */
    public static function get(string $name, string $class = '', int $size = 18): string
    {
        $path = self::$icons[$name] ?? self::$icons['link'];
        $classAttr = $class !== '' ? ' ' . htmlspecialchars($class, ENT_QUOTES, 'UTF-8') : '';
        
        return sprintf(
            '<svg xmlns="http://www.w3.org/2000/svg" width="%d" height="%d" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="tamoza-icon%s">%s</svg>',
            $size,
            $size,
            $classAttr,
            $path
        );
    }
